#include <iostream>
#include <iomanip>

struct UpdateEconomics {
    uint32_t fleetSize;
    uint32_t fullBinaryBytes;
    uint32_t deltaPatchBytes;
    double costPerMB;

    void calculateSavings() const {
        double fullTotalMB = (double)(fleetSize * fullBinaryBytes) / (1024.0 * 1024.0);
        double deltaTotalMB = (double)(fleetSize * deltaPatchBytes) / (1024.0 * 1024.0);
        double fullCost = fullTotalMB * costPerMB;
        double deltaCost = deltaTotalMB * costPerMB;
        double reduction = (1.0 - (double)deltaPatchBytes / fullBinaryBytes) * 100.0;

        std::cout << "--- DAY 47 PART 1: FOTA DELTA UPDATE ECONOMICS ---" << std::endl;
        std::cout << "Fleet Size: " << fleetSize << " devices | Cost: $" << costPerMB << "/MB" << std::endl;
        std::cout << "Full Binary: " << fullBinaryBytes / 1024 << " KB -> Total Data: " << fullTotalMB << " MB -> Cost: $" << fullCost << std::endl;
        std::cout << "Delta Patch: " << deltaPatchBytes / 1024 << " KB -> Total Data: " << deltaTotalMB << " MB -> Cost: $" << deltaCost << std::endl;
        std::cout << "Bandwidth & Cost Reduction: " << std::fixed << std::setprecision(1) << reduction << "% [OPTIMAL]" << std::endl;
    }
};

int main() {
    UpdateEconomics econ{10000, 1048576, 40960, 5.00};
    econ.calculateSavings();
    return 0;
}

#include <iostream>
#include <vector>
#include <cstdint>

struct BSDiffControl {
    int32_t diffBytes;
    int32_t extraBytes;
    int32_t oldSeekOffset;
};

void simulateBSDiffPatch(const std::vector<uint8_t>& oldBin, 
                         const std::vector<uint8_t>& diffBlock, 
                         const std::vector<uint8_t>& extraBlock, 
                         const std::vector<BSDiffControl>& controls) {
    std::vector<uint8_t> newBin;
    size_t oldPtr = 0, diffPtr = 0, extraPtr = 0;

    std::cout << "--- DAY 47 PART 2: BSDIFF RECONSTRUCTION ENGINE ---" << std::endl;
    for (size_t i = 0; i < controls.size(); ++i) {
        const auto& c = controls[i];
        // 1. Apply diff block to old binary
        for (int32_t j = 0; j < c.diffBytes; ++j) {
            uint8_t reconstructed = oldBin[oldPtr++] + diffBlock[diffPtr++];
            newBin.push_back(reconstructed);
        }
        // 2. Insert extra block
        for (int32_t j = 0; j < c.extraBytes; ++j) {
            newBin.push_back(extraBlock[extraPtr++]);
        }
        // 3. Adjust old binary seek pointer
        oldPtr += c.oldSeekOffset;
    }
    std::cout << "Reconstruction Complete! Generated " << newBin.size() << " bytes from Old Binary (" << oldBin.size() << "B)." << std::endl;
}

int main() {
    std::vector<uint8_t> oldBin = {0x48, 0x65, 0x6C, 0x6C, 0x6F, 0x20, 0x57, 0x6F, 0x72, 0x6C, 0x64};
    std::vector<uint8_t> diff = {0x00, 0x00, 0x00, 0x00, 0x00}; // Hello stays same
    std::vector<uint8_t> extra = {0x21, 0x21}; // Adds '!!'
    std::vector<BSDiffControl> ctrl = {{5, 0, 1}, {5, 2, 0}};
    simulateBSDiffPatch(oldBin, diff, extra, ctrl);
    return 0;
}

