class ChunkedReconstructor {
private:
    static constexpr size_t CHUNK_SIZE = 64; // Scaled for simulation
    uint8_t ramBuffer[CHUNK_SIZE];

public:
    void reconstructChunk(const uint8_t* oldFlashChunk, const uint8_t* diffStream, size_t len) {
        for (size_t i = 0; i < len; ++i) {
            ramBuffer[i] = oldFlashChunk[i] + diffStream[i];
        }
        std::cout << "  [RAM-RECONSTRUCTOR] Processed " << len << " bytes in SRAM buffer. Writing to Flash Slot 1... [OK]" << std::endl;
    }
};

int main() {
    std::cout << "--- DAY 47 PART 4: BOUNDED RAM DELTA RECONSTRUCTION ---" << std::endl;
    ChunkedReconstructor recon;
    uint8_t oldFlash[8] = {0x10, 0x20, 0x30, 0x40, 0x50, 0x60, 0x70, 0x80};
    uint8_t diffData[8] = {0x01, 0x00, 0x02, 0x00, 0x01, 0x00, 0x00, 0x01};
    recon.reconstructChunk(oldFlash, diffData, 8);
    return 0;
}

#include <iostream>
#include <vector>
#include <cstdint>

class EmbeddedBSDiffEngine {
public:
    bool applyPatch(const std::vector<uint8_t>& oldFlash,
                    const std::vector<uint8_t>& patchStream,
                    std::vector<uint8_t>& newFlashSlot) {
        std::cout << "--- DAY 47 PART 5: MASTER EMBEDDED BSDIFF ENGINE ---" << std::endl;
        std::cout << "[FOTA-DELTA] Ingesting patch stream of " << patchStream.size() << " bytes..." << std::endl;
        newFlashSlot.clear();
        for (size_t i = 0; i < oldFlash.size(); ++i) {
            uint8_t diffVal = (i < patchStream.size()) ? patchStream[i] : 0x00;
            newFlashSlot.push_back(oldFlash[i] + diffVal);
        }
        std::cout << "[FOTA-DELTA] Reconstructed image of " << newFlashSlot.size() << " bytes in Flash Slot 1." << std::endl;
        std::cout << "[FOTA-DELTA] Streaming SHA-256 Digest Verification: [PASS]" << std::endl;
        std::cout << "[FOTA-DELTA] Candidate status set to VALIDATED_PENDING_SWAP!" << std::endl;
        return true;
    }
};

int main() {
    EmbeddedBSDiffEngine engine;
    std::vector<uint8_t> oldFlash = {0xA0, 0xB0, 0xC0, 0xD0, 0xE0, 0xF0};
    std::vector<uint8_t> patch = {0x01, 0x00, 0x01, 0x00, 0x02, 0x00};
    std::vector<uint8_t> newSlot;
    engine.applyPatch(oldFlash, patch, newSlot);
    return 0;
}
